def is_sum_of_three_squares(n):
    if n < 0: return False
    # An integer is a sum of three squares iff it is not of the form 4^k(8m+7)
    while n > 0 and n % 4 == 0:
        n //= 4
    return n % 8 != 7

def solve():
    for m in range(1, 50):
        # We want to find a_i, b_i such that
        # sum(a_i^2) = m^2
        # sum(b_i^2) = 7*m^2
        # sum(a_i * b_i) = 0
        # for n=3, 4, 5
        for n in [3, 4, 5]:
            # This is a small search space for small m.
            # Instead of iterating over all a_i, b_i,
            # let's iterate over all a_i such that sum(a_i^2) = m^2
            import itertools
            for a in itertools.product(range(-m, m+1), repeat=n):
                if sum(x**2 for x in a) == m**2:
                    # Now find b_i such that sum(b_i^2) = 7*m^2 and sum(a_i*b_i) = 0
                    # This is still a bit large. Let's optimize.
                    # Since we only need to find ONE such b, we can iterate.
                    # However, even for m=3, 7*m^2 = 63, b_i could be up to 8.
                    # Let's use a more efficient way to find b.
                    limit = int((7*m**2)**0.5) + 1
                    for b in itertools.product(range(-limit, limit+1), repeat=n):
                        if sum(x**2 for x in b) == 7*m**2:
                            if sum(a[i]*b[i] for i in range(n)) == 0:
                                return n, m, a, b
    return None

print(solve())

def check_n4():
    for m in range(1, 100):
        # Possible a such that sum(a_i^2) = m^2
        # For n=4, we can iterate over all a_i
        limit_a = m
        for a in itertools.product(range(-limit_a, limit_a+1), repeat=4):
            if sum(x**2 for x in a) == m**2:
                # Now find b such that sum(b_i^2) = 7*m^2 and sum(a_i*b_i) = 0
                limit_b = int((7*m**2)**0.5) + 1
                for b in itertools.product(range(-limit_b, limit_b+1), repeat=4):
                    if sum(x**2 for x in b) == 7*m**2:
                        if sum(a[i]*b[i] for i in range(4)) == 0:
                            return m, a, b
    return None

