def solve():
    for k in range(1, 20):
        k2 = k*k
        V = 7 * k2
        # Iterate over all a such that sum(a_i^2) = k2
        # Since k is small, we can use itertools.product
        import itertools
        for a in itertools.product(range(-k, k+1), repeat=4):
            if sum(x**2 for x in a) == k2:
                # Check for b such that sum(a_i*b_i) = 0 and sum(b_i^2) = V
                limit_b = int(V**0.5) + 1
                for b in itertools.product(range(-limit_b, limit_b+1), repeat=4):
                    if sum(x**2 for x in b) == V:
                        if sum(a[i]*b[i] for i in range(4)) == 0:
                            return k, a, b
    return None

